def f(N: int, points: List[Tuple[int, int]]) -> int:
    result = 0
    for i in range(N):
        for j in range(i+1, N):
            if (points[i][0] <= points[j][1] and points[i][1] >= points[j][0]) or (points[i][0] >= points[j][1] and points[i][1] <= points[j][0]):
                result += 1
    return result
